---
interface Props {
    showHL?: boolean
}

const { showHL = false } = Astro.props as Props
---

<row gap-="1" align-="center" cap-="round" id="vim-navigation">
    <span>&#xe62b;</span>
    {
        showHL && (
            <button size-="sm" variant-="background2" id="btn-h">
                h
            </button>
        )
    }
    <button size-="sm" variant-="background2" id="btn-j">j</button>
    <button size-="sm" variant-="background2" id="btn-k">k</button>
    {

---
import { getCollection } from 'astro:content'

const docs = await getCollection('docs')
const talks = docs
    .filter((doc) => doc.id.startsWith('talks/'))
    .filter((doc) => !doc.id.endsWith('talks'))
    .filter((doc) => doc.data.date)
    .sort((a, b) => {
        const da = a.data.date ? new Date(a.data.date).getTime() : 0
        const db = b.data.date ? new Date(b.data.date).getTime() : 0
        return db - da
    })
    .slice(0, 6)

function formatDate(date: Date): string {
    return new Intl.DateTimeFormat('en-US', {
        year: 'numeric',
        month: 'short',
    }).format(date)

// If the user is typing in an input, textarea, select, or contenteditable element
export function isUserTyping() {
    return (
        document.activeElement &&
        (/input|textarea|select/i.test(document.activeElement.tagName) ||
            document.activeElement.hasAttribute('contenteditable'))
    )
}

// Recursively gets the first text node from a DOM element
function getFirstTextNode(element: Node | null): Node | null {
    if (!element) return null

    if (element.nodeType === Node.TEXT_NODE) {
        return element
    }

    return getFirstTextNode(element.firstChild)
}

